import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Dropdown from 'flarum/common/components/Dropdown';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { stepButton, stepDescription, stepTitle, t } from '../../common/text';
import { fullJourney, loadFull, own } from '../state';
import { actionFor, run } from '../actions';
import Ring from './Ring';
import StepRow from './StepRow';
/** The first step neither done nor skipped. */
export function nextStep(journey) {
  return journey?.steps.find(s => !s.completedAt && !s.skippedAt) ?? null;
}

/**
 * The launcher in the header: a ring with the count, and one tap for the next
 * step and its button. Press J anywhere to open it.
 *
 * 🚨 Closed, it is drawn from the member's own user — no request. Opening it
 * fetches the live counts ("2 of 3 read"), and only then.
 */
export default class Launcher extends Component {
  view() {
    const journey = fullJourney() ?? own();
    if (!journey) return null;
    const label = extractText(t('forum.launcher.label', {
      done: journey.done,
      total: journey.total
    }));
    return m(Dropdown, {
      className: "OnrampLauncher",
      buttonClassName: "Button Button--flat OnrampLauncher-button",
      menuClassName: "Dropdown-menu--right OnrampLauncher-menu",
      accessibleToggleLabel: label,
      lazyDraw: true,
      onshow: () => loadFull().then(() => m.redraw()),
      label: m("span", {
        className: "OnrampLauncher-label",
        title: label
      }, m(Ring, {
        done: journey.done + journey.skipped,
        total: journey.total,
        size: 22
      }), m("span", {
        className: "OnrampLauncher-count"
      }, journey.done, "/", journey.total))
    }, m("li", {
      className: "OnrampLauncher-panel"
    }, this.panel()));
  }
  panel() {
    const journey = fullJourney();
    if (!journey) return m(LoadingIndicator, {
      size: "small"
    });
    const next = nextStep(journey);
    const close = () => document.body.click();
    return m("div", {
      className: "OnrampPanel"
    }, m("header", {
      className: "OnrampPanel-head"
    }, m(Ring, {
      done: journey.done + journey.skipped,
      total: journey.total,
      size: 44,
      label: `${journey.done}/${journey.total}`
    }), m("div", null, m("strong", null, t('forum.launcher.title')), m("div", {
      className: "OnrampPanel-sub"
    }, t('forum.launcher.sub', {
      count: journey.total - journey.done - journey.skipped
    })))), next ? m("section", {
      className: "OnrampPanel-next"
    }, m("div", {
      className: "OnrampPanel-nextLabel"
    }, t('forum.launcher.next')), m("div", {
      className: "OnrampPanel-nextTitle"
    }, stepTitle(next)), m("p", {
      className: "OnrampPanel-nextText"
    }, stepDescription(next)), actionFor(next) ? m(Button, {
      className: "Button Button--primary Button--block",
      onclick: () => run(next, close)
    }, stepButton(next)) : null) : null, m("ol", {
      className: "OnrampPanel-steps"
    }, journey.steps.map((step, i) => m(StepRow, {
      step: step,
      index: i,
      compact: true
    }))), m(Link, {
      className: "OnrampPanel-all",
      href: app.route('onramp'),
      onclick: close
    }, t('forum.launcher.see_all')));
  }
}
flarum.reg.add('ernestdefoe-onramp', 'forum/components/Launcher', Launcher);